def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    target_list = observation.get('resources', []) + observation.get('opponent_position', [])
    def dist(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)
    if target_list:
        tx, ty = min(target_list, key=lambda t: dist(px, py, t[0], t[1]))
        dx = dy = 0
        if px < tx: dx = 1
        elif px > tx: dx = -1
        elif py < ty: dy = 1
        elif py > ty: dy = -1
        return [dx, dy]
    else:
        return [0, 0]
